function wrapLines(s,x,y,size){const words=String(s).split(' '),max=Math.floor(900/size),lines=[''];for(const w of words){if((lines.at(-1)+' '+w).trim().length>max&&lines.at(-1))lines.push(w);else lines[lines.length-1]=(lines.at(-1)+' '+w).trim();}return lines.map((v,i)=>`<tspan x="${x}" y="${y+i*(size+4)}">${esc(v)}</tspan>`).join('');}
import{experimentOptions,experimentResult,outputLabel}from './wav1-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const txt=(x,y,s,size=16)=>`<text x="${x}" y="${y}" font-size="${size}" fill="#f7f3ec" text-anchor="middle">${wrapLines(s,x,y,size)}</text>`;const line=(x,y,a,b,c='#a9ceca',w=2,dash='')=>`<path d="M${x} ${y} L${a} ${b}" fill="none" stroke="${c}" stroke-width="${w}" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;const dot=(x,y,r=5,c='#b6d8d0')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const ray=(x,y,a,b,c)=>{let mx=(x+a)/2,my=(y+b)/2,t=Math.atan2(b-y,a-x);return line(x,y,a,b,c,2)+`<path d="M${mx-9*Math.cos(t-.45)} ${my-9*Math.sin(t-.45)}L${mx} ${my}L${mx-9*Math.cos(t+.45)} ${my-9*Math.sin(t+.45)}" fill="none" stroke="${c}" stroke-width="2"/>`;};
export function waveFigure({kind='types',state='0',movie=false,progress=.3,a,b,revealed=false}={}){let k=kind.split('-')[0],o=experimentOptions[k]||experimentOptions.types,A=String(a??o.a[0][0]),B=String(b??o.b[0][0]),x=Number(A),y=Number(B),p=movie?Math.max(0,Math.min(1,progress)):.3,s='',title='',note='';
if(['types','properties','measure','spectrum','sound'].includes(k)){let longitudinal=k==='sound'||(k==='types'&&A==='longitudinal'),dir=B==='left'?-1:1,wl=k==='properties'?120*y:110,f=k==='properties'?x:2;title=longitudinal?'Local parallel oscillation · travelling compression':'Local perpendicular oscillation · travelling wave';s+=line(55,245,505,245,'#70909b',1,'4 5');let pts=[];for(let i=0;i<=80;i++){let xx=60+i*5.5,phase=2*Math.PI*(f*p-dir*(xx-60)/wl),yy=245+35*Math.sin(phase);pts.push(xx+','+yy);if(i%3===0){let base=xx,dx=longitudinal?15*Math.sin(phase):0,dy=longitudinal?0:35*Math.sin(phase);s+=dot(base+dx,245+dy,i===39?8:4,i===39?'#ef947e':'#b6d8d0');}}if(!longitudinal)s+=`<polyline points="${pts.join(' ')}" fill="none" stroke="#b6d8d0" stroke-width="2" opacity=".6"/>`;s+=txt(280,115,B==='left'?'Energy pattern travels left ←':'Energy pattern travels right →')+txt(280,330,'Highlighted point oscillates locally',14);note='Amplitude/particle spacing enlarged · playback slowed, no net material drift';if(k==='sound')s+=`<path d="M500 170 Q${500+12*Math.sin(4*Math.PI*p)} 245 500 320" fill="none" stroke="#ef947e" stroke-width="5"/>`+txt(440,370,'Solid membrane',13);if(k==='properties')s+=txt(280,375,`f = ${x} Hz · λ = ${y} m`);if(k==='measure')s+=txt(280,375,`Four intervals span ${x} m · source ${y} Hz`);if(k==='spectrum')s+=txt(280,375,`f = ${x*y} MHz · vacuum c = 300 million m/s`);}
else if(['reflection','refraction'].includes(k)){let refr=k==='refraction',inc=refr?(B==='normal'?0:35):x,rad=inc*Math.PI/180,slow=A==='slower',out=refr?(B==='normal'?0:slow?20:55):inc,rr=out*Math.PI/180;s+=`<rect x="60" y="245" width="440" height="145" fill="#a7cecf" opacity=".12"/>`+line(60,245,500,245,'#bbc9d1',3)+line(280,95,280,390,'#a7b7c2',1,'5 5');let sx=280-150*Math.sin(rad),sy=245-150*Math.cos(rad),ex=280+150*Math.sin(rr),ey=245+(refr?1:-1)*150*Math.cos(rr);s+=ray(sx,sy,280,245,'#ed947e')+ray(280,245,ex,ey,'#a9ceca')+dot(p<.5?sx+(280-sx)*p*2:280+(ex-280)*(p-.5)*2,p<.5?sy+(245-sy)*p*2:245+(ey-245)*(p-.5)*2,6,'#eccb88')+txt(380,135,'Normal',13)+txt(140,360,refr?'Different medium':'Reflecting surface',14);title=refr?'Refraction: measure rays from the normal':'Reflection: equal angles from the local normal';note=refr?'Angles illustrative · normal incidence changes speed without bending':'Rough surfaces vary their local normals; this is one selected facet';}
else if(k==='detection'){let z=p<.5?p*2:(1-p)*2;s+=line(110,245,445,245)+`<rect x="80" y="200" width="45" height="90" rx="7" fill="#9ec8c5"/><rect x="445" y="150" width="15" height="190" fill="#e5a48f"/>`+dot(125+320*z,245,9,'#ef947e')+txt(100,335,'Emitter/detector',13)+txt(445,365,'Boundary',13)+txt(280,115,p<.5?'Outward pulse':'Returning echo');title='Measure the out-and-back time';note='One-way distance is half the complete path · homogeneous medium assumed';}
else if(k==='hazards'){title='Compare supplied dose and exposure conditions';s+=txt(280,150,'UV: skin ageing / skin-cancer risk',18)+txt(280,210,'X-ray and gamma: ionising',18)+txt(280,270,'Type · dose · exposure · uncertainty',17)+txt(280,345,`${x} mSv per exposure × ${y} exposures`);note='Arithmetic comparison is not a personal risk model';}
else if(k==='applications'){title='Match a wave interaction to the requirement';s+=`<rect x="90" y="145" width="150" height="165" rx="20" fill="#ef947e" opacity=".18"/><rect x="335" y="155" width="100" height="145" rx="16" fill="#a9ceca" opacity=".2"/>`+txt(165,200,A==='thermal'?'Warm surface':'Body boundary')+txt(385,220,'Detector')+line(240,225,335,225,'#eccb88',5)+txt(280,350,B==='ir'?'Infrared band':'X-ray band');note='Suitability depends on absorption, transmission and the required signal';}
else if(k==='lenses'){let mode=Number(state)%3,virtual=mode>0,concave=mode===2;title=concave?'Concave: diverging rays, virtual image':virtual?'Convex: object inside focus, virtual image':'Convex: converging rays, real image';s+=line(50,260,510,260,'#97b5c0',1)+`<path d="${concave?'M270 120 Q292 260 270 365 L290 365 Q268 260 290 120Z':'M280 120 Q248 260 280 365 Q312 260 280 120Z'}" fill="#a9ceca" fill-opacity=".25" stroke="#b9dfd7"/>`+txt(190,290,'F',13)+txt(370,290,'F',13)+line(190,253,190,267)+line(370,253,370,267);if(!virtual){s+=line(100,260,100,170,'#ef947e',4)+ray(100,170,280,170,'#eccb88')+ray(280,170,460,350,'#eccb88')+ray(100,170,460,350,'#ed947e')+line(460,260,460,350,'#b6d8d0',4)+txt(100,140,'Object')+txt(450,385,'Real/inverted',14);}else{let ox=concave?90:230,oy=190,ix=concave?218.929:167.5,iy=concave?237.5:102.5;s+=line(ox,260,ox,oy,'#ed947e',4)+ray(ox,oy,280,oy,'#eccb88')+ray(280,oy,480,concave?34.444:345.556,'#eccb88')+ray(ox,oy,concave?480:365,concave?333.684:379,'#ed947e')+line(280,oy,ix,iy,'#eccb88',2,'4 4')+line(280,260,ix,iy,'#ed947e',2,'4 4')+line(ix,260,ix,iy,'#b6d8d0',4)+txt(ix,iy-20,'Virtual/upright',13);}note='Schematic ray paths · supplied height-ratio investigation is separate';}
else if(k==='colour'){title='An ideal filter selects from incoming light';let c=A==='red'?'#ef947e':'#8eafef',trans=A===B;s+=line(60,245,270,245,c,12)+`<rect x="270" y="150" width="24" height="190" rx="4" fill="${B==='red'?'#ef947e':'#8eafef'}" opacity=".7"/>`+(revealed&&trans?line(295,245,490,245,c,12):'')+txt(130,125,A+' input')+txt(365,360,B+' filter');note='Text labels encode the band · real filters are not perfectly selective';}
else if(k==='blackbody'){title='Hotter spectra: higher output, shorter peak wavelength';s+=line(65,340,500,340)+line(65,340,65,95);for(let j=0;j<2;j++){let pts=Array.from({length:81},(_,i)=>{let xx=75+i*5.1,z=(xx-70)/(j?65:95),yy=340-(j?220:140)*z*z*Math.exp(2-2*z);return xx+','+yy;}).join(' ');s+=`<polyline points="${pts}" fill="none" stroke="${j?'#ef947e':'#a9ceca'}" stroke-width="3"/>`;}s+=txt(280,375,'Wavelength →')+txt(280,115,A==='higher'?'Selected: hotter spectrum':'Selected: cooler spectrum');note='Qualitative curves, not a calibrated Planck-law calculation';}
else if(k==='infrared'){title='Equal-temperature surface comparison';s+=`<rect x="135" y="150" width="145" height="170" rx="10" fill="${A==='matt'?'#172638':'#b0bdc7'}" stroke="#d5ded7"/><rect x="395" y="180" width="45" height="95" rx="8" fill="#a9ceca"/>`+txt(210,350,A==='matt'?'Matt black':'Shiny reflective')+txt(420,315,'Detector',13)+txt(280,105,B==='hot'?'Hot common temperature':'Warm common temperature');note='Keep area, angle, distance, temperature and detector conditions controlled';}
if(a&&b&&revealed)s+=txt(280,460,outputLabel(k,experimentResult(k,A,B).value),14);
return `<svg class="shell-diagram wav1-diagram" viewBox="0 0 560 480" role="img" aria-label="${esc(k+' labelled wave model'+(revealed?' with revealed output':''))}">${txt(280,50,title,15)}${s}${txt(280,420,note,12)}</svg>`;}
